script:
frappe.ui.form.on('Lead Management', {
    refresh: function(frm) {
        if (!frm.is_new()) {
            frm.add_custom_button(__('Call Log'), function() {
                // Set route options to pre-fill the lead field
                frappe.route_options = {
                    'lead': frm.doc.name
                };
                // Open new Call Log form
                frappe.new_doc('Call Log');
            });
        }
    }
});

frappe.ui.form.on('Lead Management', {
    refresh: function(frm) {
        if (!frm.is_new()) {
            // Add Call Log button
            frm.add_custom_button(__('Call Log'), function() {
                frappe.route_options = {'lead': frm.doc.name};
                frappe.new_doc('Call Log');
            });
            
            // Load and display call logs
            load_call_logs(frm);
        }
    }
});

function load_call_logs(frm) {
    // Fetch all Call Logs for this lead
    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'Call Log',
            filters: {
                'lead': frm.doc.name
            },
            fields: ['name', 'call_date', 'call_outcome', 'lead_response', 'call_duration', 'call_notes'],
            order_by: 'call_date desc',
            limit: 50
        },
        callback: function(r) {
            console.log('Call Logs Response:', r.message); // Debug line
            if (r.message && r.message.length > 0) {
                display_call_logs(frm, r.message);
            } else {
                frm.fields_dict.call_logs.$wrapper.html('<p class="text-muted" style="padding: 15px;">No call logs found for this lead</p>');
            }
        }
    });
}

function display_call_logs(frm, logs) {
    let html = '<div class="call-logs-container" style="padding: 10px;">';
    html += '<table class="table table-bordered table-hover">';
    html += '<thead><tr>';
    html += '<th>Date</th>';
    html += '<th>Outcome</th>';
    html += '<th>Response</th>';
    html += '<th>Duration</th>';
    html += '<th>Notes</th>';
    html += '<th>Action</th>';
    html += '</tr></thead><tbody>';
    
    logs.forEach(function(log) {
        // Format date
        let date = log.call_date ? frappe.datetime.str_to_user(log.call_date) : '-';
        
        // Format duration
        let duration = log.call_duration || '-';
        
        // Truncate notes (remove HTML tags)
        let notes = '-';
        if (log.call_notes) {
            let temp = document.createElement('div');
            temp.innerHTML = log.call_notes;
            let text = temp.textContent || temp.innerText || '';
            notes = text.length > 50 ? text.substring(0, 50) + '...' : text;
        }
        
        // Response badge color
        let badge_color = 'secondary';
        if (log.lead_response === 'Yes - Interested') badge_color = 'success';
        else if (log.lead_response === 'No - Not Interested') badge_color = 'danger';
        else if (log.lead_response === 'Maybe - Need Follow Up') badge_color = 'warning';
        
        html += '<tr>';
        html += '<td>' + date + '</td>';
        html += '<td>' + (log.call_outcome || '-') + '</td>';
        html += '<td><span class="badge badge-' + badge_color + '">' + (log.lead_response || '-') + '</span></td>';
        html += '<td>' + duration + '</td>';
        html += '<td>' + notes + '</td>';
        html += '<td><a href="/app/call-log/' + log.name + '" target="_blank">View</a></td>';
        html += '</tr>';
    });
    
    html += '</tbody></table>';
    html += '</div>';
    
    // Inject HTML into the field
    frm.fields_dict.call_logs.$wrapper.html(html);
}

frappe.ui.form.on('Lead Management', {
    refresh: function(frm) {
        if (!frm.is_new()) {
            // Add Follow Up button
            frm.add_custom_button(__('Follow Up'), function() {
                frappe.route_options = {'lead': frm.doc.name};
                frappe.new_doc('Follow Up');
            });
            
            // Load and display follow ups
            load_follow_ups(frm);
        }
    }
});

function load_follow_ups(frm) {
    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'Follow Up',
            filters: {'lead': frm.doc.name},
            fields: ['name', 'followup_date', 'followup_status', 'followup_method', 'response', 'next_action', 'followup_notes'],
            order_by: 'followup_date desc',
            limit: 50
        },
        callback: function(r) {
            console.log('Follow Ups Response:', r.message);
            if (r.message && r.message.length > 0) {
                display_follow_ups(frm, r.message);
            } else {
                frm.fields_dict.follow_ups.$wrapper.html('<p class="text-muted" style="padding: 15px;">No follow ups found for this lead</p>');
            }
        }
    });
}

function display_follow_ups(frm, followups) {
    let html = '<div class="followups-container" style="padding: 10px;">';
    html += '<table class="table table-bordered table-hover">';
    html += '<thead><tr>';
    html += '<th>Date</th>';
    html += '<th>Method</th>';
    html += '<th>Status</th>';
    html += '<th>Response</th>';
    html += '<th>Next Action</th>';
    html += '<th>Notes</th>';
    html += '<th>Action</th>';
    html += '</tr></thead><tbody>';
    
    followups.forEach(function(followup) {
        // Format date
        let date = followup.followup_date ? frappe.datetime.str_to_user(followup.followup_date) : '-';
        
        // Truncate notes
        let notes = '-';
        if (followup.followup_notes) {
            let temp = document.createElement('div');
            temp.innerHTML = followup.followup_notes;
            let text = temp.textContent || temp.innerText || '';
            notes = text.length > 40 ? text.substring(0, 40) + '...' : text;
        }
        
        // Status badge color
        let status_color = 'secondary';
        if (followup.followup_status === 'Completed') status_color = 'success';
        else if (followup.followup_status === 'Pending') status_color = 'warning';
        else if (followup.followup_status === 'Cancelled') status_color = 'danger';
        else if (followup.followup_status === 'Scheduled') status_color = 'info';
        else if (followup.followup_status === 'Rescheduled') status_color = 'primary';
        
        // Response badge color
        let response_color = 'secondary';
        if (followup.response === 'Interested' || followup.response === 'Ready to Buy') response_color = 'success';
        else if (followup.response === 'Not Interested') response_color = 'danger';
        else if (followup.response === 'Need More Time') response_color = 'warning';
        else if (followup.response === 'No Response') response_color = 'secondary';
        
        html += '<tr>';
        html += '<td>' + date + '</td>';
        html += '<td>' + (followup.followup_method || '-') + '</td>';
        html += '<td><span class="badge badge-' + status_color + '">' + (followup.followup_status || '-') + '</span></td>';
        html += '<td><span class="badge badge-' + response_color + '">' + (followup.response || '-') + '</span></td>';
        html += '<td>' + (followup.next_action || '-') + '</td>';
        html += '<td>' + notes + '</td>';
        html += '<td><a href="/app/follow-up/' + followup.name + '" target="_blank">View</a></td>';
        html += '</tr>';
    });
    
    html += '</tbody></table>';
    html += '</div>';
    
    frm.fields_dict.follow_ups.$wrapper.html(html);
}

frappe.ui.form.on('Lead Management', {
    refresh: function(frm) {
        if (!frm.is_new()) {
            // Existing buttons (Call Log, Follow Up)
            frm.add_custom_button(__('Call Log'), function() {
                frappe.route_options = {'lead': frm.doc.name};
                frappe.new_doc('Call Log');
            });
            
            frm.add_custom_button(__('Follow Up'), function() {
                frappe.route_options = {'lead': frm.doc.name};
                frappe.new_doc('Follow Up');
            });
            
            // NEW: Create Quotation button
            frm.add_custom_button(__('Create Quotation'), function() {
                frappe.route_options = {
                    'lead': frm.doc.name,
                    'lead_name': frm.doc.lead_name,
                    'company_name': frm.doc.company_name,
                    'email': frm.doc.email_id,
                    'phone': frm.doc.phone
                };
                frappe.new_doc('Quotation');
            }, __('Create'));
            
            // Load existing data
            load_call_logs(frm);
            load_follow_ups(frm);
            load_quotations(frm); // NEW
        }
    }
});

// Your existing functions (load_call_logs, load_follow_ups, etc.)

// NEW: Load Quotations function
function load_quotations(frm) {
    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'Quotation',
            filters: {'lead': frm.doc.name},
            fields: ['name', 'quotation_date', 'valid_till', 'status', 'grand_total'],
            order_by: 'quotation_date desc',
            limit: 50
        },
        callback: function(r) {
            console.log('Quotations Response:', r.message);
            if (r.message && r.message.length > 0) {
                display_quotations(frm, r.message);
            } else {
                if (frm.fields_dict.quotations) {
                    frm.fields_dict.quotations.$wrapper.html('<p class="text-muted" style="padding: 15px;">No quotations found</p>');
                }
            }
        }
    });
}

function display_quotations(frm, quotations) {
    let html = '<div class="quotations-container" style="padding: 10px;">';
    html += '<table class="table table-bordered table-hover">';
    html += '<thead><tr>';
    html += '<th>Quotation #</th>';
    html += '<th>Date</th>';
    html += '<th>Valid Till</th>';
    html += '<th>Amount</th>';
    html += '<th>Status</th>';
    html += '<th>Action</th>';
    html += '</tr></thead><tbody>';
    
    quotations.forEach(function(quotation) {
        let date = quotation.quotation_date ? frappe.datetime.str_to_user(quotation.quotation_date) : '-';
        let valid_till = quotation.valid_till ? frappe.datetime.str_to_user(quotation.valid_till) : '-';
        let amount = quotation.grand_total ? frappe.format(quotation.grand_total, {fieldtype: 'Currency'}) : '-';
        
        // Status badge color
        let status_color = 'secondary';
        if (quotation.status === 'Accepted') status_color = 'success';
        else if (quotation.status === 'Rejected') status_color = 'danger';
        else if (quotation.status === 'Sent') status_color = 'info';
        else if (quotation.status === 'Expired') status_color = 'warning';
        else if (quotation.status === 'Draft') status_color = 'secondary';
        
        html += '<tr>';
        html += '<td><strong>' + quotation.name + '</strong></td>';
        html += '<td>' + date + '</td>';
        html += '<td>' + valid_till + '</td>';
        html += '<td><strong>' + amount + '</strong></td>';
        html += '<td><span class="badge badge-' + status_color + '">' + (quotation.status || 'Draft') + '</span></td>';
        html += '<td><a href="/app/quotation/' + quotation.name + '" target="_blank">View</a></td>';
        html += '</tr>';
    });
    
    html += '</tbody></table></div>';
    
    if (frm.fields_dict.quotations) {
        frm.fields_dict.quotations.$wrapper.html(html);
    }
}

frappe.ui.form.on('Lead Management', {
    refresh: function(frm) {
        if (!frm.is_new()) {
            frm.add_custom_button(__('Create Opportunity'), function() {
