function display_opportunities(frm, opportunities) {
    let html = '<div class="opportunities-container" style="padding: 10px;">';
    html += '<table class="table table-bordered table-hover">';
    html += '<thead><tr>';
    html += '<th>Opportunity #</th>';
    html += '<th>Name</th>';
    html += '<th>Sales Stage</th>';
    html += '<th>Probability</th>';
    html += '<th>Expected Revenue</th>';
    html += '<th>Close Date</th>';
    html += '<th>Status</th>';
    html += '<th>Action</th>';
    html += '</tr></thead><tbody>';
    
    opportunities.forEach(function(opp) {
        let close_date = opp.expected_close_date ? frappe.datetime.str_to_user(opp.expected_close_date) : '-';
        let revenue = opp.expected_revenue ? frappe.format(opp.expected_revenue, {fieldtype: 'Currency'}) : '-';
        let probability = opp.probability ? opp.probability + '%' : '-';
        
        // Sales Stage color
        let stage_color = 'secondary';
        if (opp.sales_stage === 'Closed Won') stage_color = 'success';
        else if (opp.sales_stage === 'Closed Lost') stage_color = 'danger';
        else if (opp.sales_stage === 'Negotiation') stage_color = 'warning';
        else if (opp.sales_stage === 'Proposal') stage_color = 'info';
        else if (opp.sales_stage === 'Qualification') stage_color = 'primary';
        
        // Status badge color
        let status_color = 'secondary';
        if (opp.status === 'Won') status_color = 'success';
        else if (opp.status === 'Lost') status_color = 'danger';
        else if (opp.status === 'Quotation Sent') status_color = 'info';
        else if (opp.status === 'In Progress') status_color = 'warning';
        
        html += '<tr>';
        html += '<td><strong>' + opp.name + '</strong></td>';
        html += '<td>' + (opp.opportunity_name || '-') + '</td>';
        html += '<td><span class="badge badge-' + stage_color + '">' + (opp.sales_stage || '-') + '</span></td>';
        html += '<td>' + probability + '</td>';
        html += '<td><strong>' + revenue + '</strong></td>';
        html += '<td>' + close_date + '</td>';
        html += '<td><span class="badge badge-' + status_color + '">' + (opp.status || '-') + '</span></td>';
        html += '<td><a href="/app/opportunity/' + opp.name + '" target="_blank">View</a></td>';
        html += '</tr>';
    });
    
    html += '</tbody></table></div>';
    
    if (frm.fields_dict.opportunities) {
        frm.fields_dict.opportunities.$wrapper.html(html);
    }
}

frappe.ui.form.on('Quotation', {
